94	+import { describe, expect, it } from "vitest";
95	+import { WORLD_STEPS_PER_SECOND } from "../sailing.js";
96	+import {
97	+  RUIN_COMPLETION_GOLD,
98	+  RUIN_LOCKOUT_SECONDS,
99	+  RUIN_SYMBOLS,
100	+  ruinRules,
101	+  validateRuinRules,
102	+} from "./index.js";
103	+
104	+function issuesOf(candidate: unknown): string[] {
105	+  const result = validateRuinRules(candidate);
106	+  return result.ok ? [] : result.issues;
107	+}
108	+
109	+describe("ruin rules (§3, §11)", () => {
110	+  it("lock out for three seconds in world ticks, pay 40 gold, and keep six symbols and a 4 × 4 grid", () => {
111	+    expect(RUIN_LOCKOUT_SECONDS).toBe(3);
112	+    expect(ruinRules.lockoutTicks).toBe(RUIN_LOCKOUT_SECONDS * WORLD_STEPS_PER_SECOND);
113	+    expect(ruinRules.lockoutTicks).toBe(60);
114	+    expect(RUIN_COMPLETION_GOLD).toBe(40);
115	+    expect(ruinRules.completionGold).toBe(40);
116	+    expect(ruinRules.symbols).toEqual([...RUIN_SYMBOLS]);
117	+    expect(ruinRules.symbols).toHaveLength(6);
118	+    expect(ruinRules.sequenceLength).toBe(3);
119	+    expect(ruinRules.gridSize).toBe(4);
120	+    expect([ruinRules.minPathMoves, ruinRules.maxPathMoves]).toEqual([4, 6]);
121	+    expect([ruinRules.minBlockedCells, ruinRules.maxBlockedCells]).toEqual([3, 5]);
122	+    expect(validateRuinRules(ruinRules)).toEqual({ ok: true, value: ruinRules });
123	+  });
124	+
125	+  it("refuse a negative or fractional lockout, negative gold and unknown fields", () => {
126	+    expect(issuesOf({ ...ruinRules, lockoutTicks: -1 })[0]).toMatch(/^lockoutTicks:/);
127	+    expect(issuesOf({ ...ruinRules, lockoutTicks: 1.5 })[0]).toMatch(/^lockoutTicks:/);
128	+    expect(issuesOf({ ...ruinRules, completionGold: -40 })[0]).toMatch(/^completionGold:/);
129	+    expect(issuesOf({ ...ruinRules, extra: 1 })).toHaveLength(1);
130	+  });
131	+
132	+  it("refuse a path-length range the grid cannot hold, or an empty one", () => {
133	+    // 4 × 4 with 3 blocked cells leaves 13 open cells: no shortest path is longer than 12 moves.
134	+    expect(issuesOf({ ...ruinRules, minPathMoves: 13, maxPathMoves: 14 })).toEqual([
135	+      "minPathMoves: a 4 × 4 grid with 3 blocked cells holds no path of 13 moves",
136	+    ]);
137	+    expect(issuesOf({ ...ruinRules, minPathMoves: 12, maxPathMoves: 12 })).toEqual([]);
138	+    expect(issuesOf({ ...ruinRules, gridSize: 2 })).toEqual([
