160	+import { z } from "zod";
161	+import { formatIssues, type ValidationResult } from "../rules.js";
162	+import { WORLD_STEPS_PER_SECOND } from "../sailing.js";
163	+
164	+/** §3: a wrong attempt at a ruin locks that player out of that ruin this long. */
165	+export const RUIN_LOCKOUT_SECONDS = 3;
166	+/** §11: a fresh ruin completion pays this much, once per player per ruin. */
167	+export const RUIN_COMPLETION_GOLD = 40;
168	+/** The six carved symbols of a sequence ruin, in their fixed display order. */
169	+export const RUIN_SYMBOLS = ["sun", "moon", "tide", "storm", "anchor", "skull"] as const;
170	+/** A sequence ruin's answer: this many distinct symbols in order. */
171	+export const RUIN_SEQUENCE_LENGTH = 3;
172	+/** A navigation ruin's grid is this many cells on a side. */
173	+export const RUIN_GRID_SIZE = 4;
174	+/** A navigation ruin's shortest path from start to goal is this many moves or more… */
175	+export const RUIN_MIN_PATH_MOVES = 4;
176	+/** …and this many or fewer. */
177	+export const RUIN_MAX_PATH_MOVES = 6;
178	+/** A navigation ruin blocks this many cells or more… */
179	+export const RUIN_MIN_BLOCKED_CELLS = 3;
180	+/** …and this many or fewer. */
181	+export const RUIN_MAX_BLOCKED_CELLS = 5;
182	+
183	+export const ruinSymbolSchema = z.enum(RUIN_SYMBOLS);
184	+export type RuinSymbol = z.infer<typeof ruinSymbolSchema>;
185	+
186	+/** The compass moves of a navigation answer. North is towards smaller y (y grows down, as on the sea). */
187	+export const RUIN_MOVES = ["N", "E", "S", "W"] as const;
188	+export const ruinMoveSchema = z.enum(RUIN_MOVES);
189	+export type RuinMove = z.infer<typeof ruinMoveSchema>;
190	+
191	+/** The ruin rules (§3, §11) in world ticks (20 a second), gold and cells. */
192	+export const ruinRulesSchema = z
193	+  .strictObject({
194	+    /** World ticks a wrong attempt locks the player out of that ruin. */
195	+    lockoutTicks: z.int().nonnegative(),
196	+    /** Gold for each player's first solve of each ruin. */
197	+    completionGold: z.int().nonnegative(),
198	+    /** The symbols a sequence ruin shows, in display order. */
199	+    symbols: z.array(ruinSymbolSchema).min(1),
200	+    sequenceLength: z.int().positive(),
201	+    gridSize: z.int().min(2),
202	+    minPathMoves: z.int().positive(),
203	+    maxPathMoves: z.int().positive(),
204	+    minBlockedCells: z.int().nonnegative(),
205	+    maxBlockedCells: z.int().nonnegative(),
206	+  })
207	+  .superRefine((rules, ctx) => {
208	+    const issue = (path: string, message: string) => ctx.addIssue({ code: "custom", path: [path], message });
209	+    if (new Set(rules.symbols).size !== rules.symbols.length) issue("symbols", "the symbols must be distinct");
210	+    if (rules.sequenceLength >= rules.symbols.length) {
211	+      issue("sequenceLength", `a sequence of ${rules.sequenceLength} needs more than ${rules.symbols.length} symbols, or every symbol is in it`);
212	+    }
213	+    if (rules.minPathMoves > rules.maxPathMoves) {
214	+      issue("minPathMoves", `the path range ${rules.minPathMoves}–${rules.maxPathMoves} is empty`);
215	+    }
216	+    if (rules.minBlockedCells > rules.maxBlockedCells) {
217	+      issue("minBlockedCells", `the blocked-cell range ${rules.minBlockedCells}–${rules.maxBlockedCells} is empty`);
218	+    }
219	+    const cells = rules.gridSize * rules.gridSize;
220	+    // A shortest path visits distinct open cells, so it has at most (open cells - 1) moves.
221	+    const longest = cells - rules.minBlockedCells - 1;
222	+    if (rules.minPathMoves > longest) {
223	+      issue("minPathMoves", `a ${rules.gridSize} × ${rules.gridSize} grid with ${rules.minBlockedCells} blocked cells holds no path of ${rules.minPathMoves} moves`);
224	+    }
225	+    if (rules.maxBlockedCells > cells - 2) {
226	+      issue("maxBlockedCells", `a ${rules.gridSize} × ${rules.gridSize} grid needs an open start and goal`);
227	+    }
228	+  });
229	+
230	+export type RuinRules = z.infer<typeof ruinRulesSchema>;
231	+
232	+export const ruinRules: RuinRules = {
233	+  lockoutTicks: RUIN_LOCKOUT_SECONDS * WORLD_STEPS_PER_SECOND,
234	+  completionGold: RUIN_COMPLETION_GOLD,
235	+  symbols: [...RUIN_SYMBOLS],
236	+  sequenceLength: RUIN_SEQUENCE_LENGTH,
237	+  gridSize: RUIN_GRID_SIZE,
238	+  minPathMoves: RUIN_MIN_PATH_MOVES,
239	+  maxPathMoves: RUIN_MAX_PATH_MOVES,
240	+  minBlockedCells: RUIN_MIN_BLOCKED_CELLS,
241	+  maxBlockedCells: RUIN_MAX_BLOCKED_CELLS,
242	+};
243	+
244	+export function validateRuinRules(candidate: unknown): ValidationResult<RuinRules> {
245	+  const parsed = ruinRulesSchema.safeParse(candidate);
246	+  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
247	+}
