265	new file mode 100644
266	index 0000000..a2a70ac
267	--- /dev/null
268	+++ b/packages/simulation/src/ruins/determinism.test.ts
269	@@ -0,0 +1,201 @@
270	+import { describe, expect, it } from "vitest";
271	+import { canonicalize } from "../hash.js";
272	+import { nextInt } from "../random.js";
273	+import {
274	+  answerRuin,
275	+  clueFor,
276	+  createRuins,
277	+  hashState,
278	+  openRuin,
279	+  reportPresence,
280	+  ruinIslands,
281	+  RUIN_MOVES,
282	+  RUIN_SYMBOLS,
283	+  type Ruin,
284	+  type RuinAttempt,
285	+  type RuinEvent,
286	+  type RuinsState,
287	+} from "./index.js";
288	+
289	+const ISLANDS = [0, 1, 2, 3].map((island) => ({ island, sourceIds: [`source-${island}-0`, `source-${island}-1`] }));
290	+const PLAYERS = ["p1", "p10", "p2", "Crew"];
291	+
292	+type Draw = (bound: number) => number;
293	+
294	+function generator(seed: number): Draw {
295	+  let rng = seed;
296	+  return (bound) => {
297	+    const drawn = nextInt(rng, bound);
298	+    rng = drawn.state;
299	+    return drawn.value;
300	+  };
301	+}
302	+
303	+function frozen<T>(value: T): T {
304	+  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
305	+    Object.freeze(value);
306	+    for (const item of Object.values(value)) frozen(item);
307	+  }
308	+  return value;
309	+}
310	+
311	+/** A right answer from the secret puzzle: the sequence, or a minimum route found by breadth-first search. */
312	+function rightAnswer(ruin: Ruin): RuinAttempt {
313	+  const puzzle = ruin.puzzle;
314	+  if (puzzle.kind === "sequence") return { kind: "sequence", symbols: [...puzzle.answer] };
315	+  const blocked = new Set(puzzle.blocked.map(({ x, y }) => `${x},${y}`));
316	+  const routes = new Map<string, RuinAttempt & { kind: "navigation" }>([[`${puzzle.start.x},${puzzle.start.y}`, { kind: "navigation", moves: [] }]]);
317	+  const queue = [puzzle.start];
318	+  const delta = { N: [0, -1], E: [1, 0], S: [0, 1], W: [-1, 0] } as const;
319	+  for (let head = 0; head < queue.length; head++) {
320	+    const { x, y } = queue[head]!;
321	+    const route = routes.get(`${x},${y}`)!;
322	+    if (x === puzzle.goal.x && y === puzzle.goal.y) return route;
323	+    for (const move of RUIN_MOVES) {
324	+      const next = { x: x + delta[move][0], y: y + delta[move][1] };
325	+      const key = `${next.x},${next.y}`;
326	+      if (next.x < 0 || next.y < 0 || next.x >= puzzle.size || next.y >= puzzle.size || blocked.has(key) || routes.has(key)) continue;
327	+      routes.set(key, { kind: "navigation", moves: [...route.moves, move] });
328	+      queue.push(next);
329	+    }
330	+  }
331	+  throw new Error("no route");
332	+}
333	+
334	+function randomAttempt(ruin: Ruin, draw: Draw): RuinAttempt {
335	+  if (ruin.puzzle.kind === "sequence") {
336	+    const pool = [...RUIN_SYMBOLS];
337	+    return { kind: "sequence", symbols: [0, 1, 2].map(() => pool.splice(draw(pool.length), 1)[0]!) };
338	+  }
339	+  return { kind: "navigation", moves: Array.from({ length: 1 + draw(7) }, () => RUIN_MOVES[draw(4)]!) };
340	+}
341	+
342	+interface Run {
343	+  /** Every step's result, serialised. */
344	+  readonly results: string[];
345	+  /** `hashState` every 20 steps and at the end (hashing every step is slow). */
346	+  readonly hashes: string[];
347	+  readonly events: RuinEvent[];
348	+  readonly final: RuinsState;
349	+}
350	+
351	+/**
352	+ * A seeded session: players moor at islands and cast off, enter and leave duels, open ruins, answer right and wrong
353	+ * (sometimes during a lockout or after solving), and repeat or send stale requests.
354	+ */
355	+function runSession(seed: number): Run {
356	+  const draw = generator(seed);
357	+  let state = frozen(createRuins({ seed, islands: ISLANDS }));
358	+  const islands = ruinIslands(state);
359	+  const results: string[] = [];
360	+  const hashes = [hashState(state)];
361	+  const events: RuinEvent[] = [];
362	+  let tick = 0;
363	+  for (let step = 0; step < 200; step++) {
364	+    tick += draw(4) === 0 ? 0 : 1 + draw(40);
365	+    const playerId = PLAYERS[draw(PLAYERS.length)]!;
366	+    const island = islands[draw(islands.length)]!;
367	+    const ruin = state.ruins[String(island)]!;
368	+    const roll = draw(12);
369	+    const requestTick = draw(20) === 0 ? Math.max(0, tick - 5) : tick;
370	+    let next: RuinsState;
371	+    if (roll < 3) {
372	+      const where = draw(3) === 0 ? null : island;
373	+      const reported = reportPresence(state, { playerId, island: where, inDuel: draw(6) === 0, tick: requestTick });
374	+      results.push(JSON.stringify(reported.result));
375	+      next = reported.state;
376	+    } else if (roll < 6) {
377	+      const opened = openRuin(state, { playerId, island, tick: requestTick });
378	+      results.push(JSON.stringify(opened.result));
379	+      next = opened.state;
380	+    } else {
381	+      const attempt = roll < 9 ? rightAnswer(ruin) : randomAttempt(ruin, draw);
382	+      const answered = answerRuin(state, { playerId, island, tick: requestTick, attempt });
383	+      results.push(JSON.stringify(answered.result));
384	+      events.push(...answered.result.events);
385	+      next = answered.state;
386	+    }
387	+    state = frozen(next);
388	+    if (step % 20 === 19) hashes.push(hashState(state));
389	+  }
390	+  hashes.push(hashState(state));
391	+  return { results, hashes, events, final: state };
392	+}
393	+
394	+function integersOnly(value: unknown): boolean {
395	+  if (typeof value === "number") return Number.isSafeInteger(value);
396	+  if (Array.isArray(value)) return value.every(integersOnly);
