806	+/** Puts (or with null, removes) a player's entry in a list sorted by player id. */
807	+function upsert<T extends { readonly playerId: string }>(list: readonly T[], playerId: string, entry: T | null): T[] {
808	+  const rest = list.filter((item) => item.playerId !== playerId);
809	+  return entry === null ? rest : [...rest, entry].sort(byPlayer);
810	+}
811	+
812	+function withRuin(state: RuinsState, ruin: Ruin): RuinsState {
813	+  return { ...state, ruins: { ...state.ruins, [String(ruin.island)]: ruin } };
814	+}
815	+
816	+// ---------------------------------------------------------------------------------------------------------------
817	+// Presence
818	+
819	+export interface ReportPresenceRequest {
820	+  readonly playerId: string;
821	+  /** The island whose dock the player is moored at, or null when at sea (or anywhere without a ruin). */
822	+  readonly island: number | null;
823	+  readonly inDuel: boolean;
824	+  readonly tick: number;
825	+}
826	+
827	+export interface PresenceResult {
828	+  readonly ok: boolean;
829	+  readonly rejection: RuinRejection | null;
830	+  /** The islands whose ruin session this report closed. */
831	+  readonly closed: readonly number[];
832	+}
833	+
834	+/**
835	+ * The caller reports where a player is whenever it changes (it may report every tick; an unchanged report is a
836	+ * duplicate). Being elsewhere than a ruin's island, or in a duel, closes the player's session there. Lockouts stay.
837	+ */
838	+export function reportPresence(state: RuinsState, request: ReportPresenceRequest): RuinStep<PresenceResult> {
839	+  const { playerId, island, inDuel, tick } = request;
840	+  const reject = (rejection: RuinRejection): RuinStep<PresenceResult> => ({ state, result: { ok: false, rejection, closed: [] } });
841	+  const bad = tickRejection(state, tick);
842	+  if (bad) return reject(bad);
843	+  if (!isPlayerId(playerId) || (island !== null && !isIsland(island)) || typeof inDuel !== "boolean") return reject("invalid-request");
844	+  const current = presenceOf(state, playerId);
845	+  if (current.island === island && current.inDuel === inDuel) return reject("duplicate");
846	+  const closed: number[] = [];
847	+  const ruins: Record<string, Ruin> = { ...state.ruins };
848	+  for (const [key, ruin] of Object.entries(state.ruins)) {
849	+    if (!sessionOf(ruin, playerId) || (!inDuel && ruin.island === island)) continue;
850	+    ruins[key] = { ...ruin, sessions: upsert(ruin.sessions, playerId, null) };
851	+    closed.push(ruin.island);
852	+  }
853	+  const entry: RuinPresence | null = island === null && !inDuel ? null : { playerId, island, inDuel };
854	+  const next: RuinsState = { ...state, tick, ruins, presence: upsert(state.presence, playerId, entry) };
855	+  return { state: next, result: { ok: true, rejection: null, closed: closed.sort((a, b) => a - b) } };
856	+}
857	+
858	+// ---------------------------------------------------------------------------------------------------------------
859	+// Opening a ruin
860	+
861	+export interface OpenRuinRequest {
862	+  readonly playerId: string;
863	+  readonly island: number;
864	+  readonly tick: number;
865	+}
866	+
867	+export interface OpenResult {
868	+  readonly ok: boolean;
869	+  readonly rejection: RuinRejection | null;
870	+  /** The clue, for a player with a session at this ruin (a repeated open gets it again); otherwise null. */
871	+  readonly clue: RuinClue | null;
872	+  /** The tick before which this player's attempts here are refused; 0 when never locked out. */
873	+  readonly lockedUntil: number;
874	+  /** Whether this player has already solved this ruin. */
875	+  readonly solved: boolean;
876	+}
877	+
878	+/** Starts a player's session at the ruin of the island they are moored at and hands them its clue. */
879	+export function openRuin(state: RuinsState, request: OpenRuinRequest): RuinStep<OpenResult> {
880	+  const { playerId, island, tick } = request;
881	+  const ruin = isIsland(island) ? findRuin(state, island) : undefined;
882	+  const reject = (rejection: RuinRejection): RuinStep<OpenResult> => {
883	+    const session = ruin && isPlayerId(playerId) ? sessionOf(ruin, playerId) : undefined;
884	+    return {
885	+      state,
886	+      result: {
887	+        ok: false,
888	+        rejection,
889	+        clue: session ? clueFor(ruin!) : null,
890	+        lockedUntil: ruin && isPlayerId(playerId) ? lockedUntil(ruin, playerId) : 0,
891	+        solved: ruin !== undefined && isPlayerId(playerId) && hasSolved(ruin, playerId),
892	+      },
893	+    };
894	+  };
895	+  const bad = tickRejection(state, tick);
896	+  if (bad) return reject(bad);
897	+  if (!isPlayerId(playerId) || !isIsland(island)) return reject("invalid-request");
898	+  if (!ruin) return reject("unknown-ruin");
899	+  const presence = presenceOf(state, playerId);
900	+  if (presence.inDuel) return reject("in-duel");
901	+  if (presence.island !== island) return reject("not-at-ruin");
902	+  if (sessionOf(ruin, playerId)) return reject("duplicate");
903	+  const opened: Ruin = { ...ruin, sessions: upsert(ruin.sessions, playerId, { playerId, openedTick: tick }) };
904	+  return {
905	+    state: withRuin({ ...state, tick }, opened),
906	+    result: { ok: true, rejection: null, clue: clueFor(opened), lockedUntil: lockedUntil(ruin, playerId), solved: hasSolved(ruin, playerId) },
907	+  };
908	+}
909	+
910	+// ---------------------------------------------------------------------------------------------------------------
911	+// Answering
912	+
913	+export interface AnswerRuinRequest {
914	+  readonly playerId: string;
915	+  readonly island: number;
916	+  readonly tick: number;
917	+  readonly attempt: RuinAttempt;
918	+}
919	+
920	+export type AnswerOutcome = "solved" | "wrong";
921	+
922	+export interface AnswerResult {
923	+  readonly ok: boolean;
924	+  readonly rejection: RuinRejection | null;
925	+  readonly outcome: AnswerOutcome | null;
926	+  /** The tick before which this player's attempts here are refused; 0 when never locked out. */
927	+  readonly lockedUntil: number;
928	+  /** For the caller to apply to the ledger, in order. */
929	+  readonly events: readonly RuinEvent[];
930	+}
931	+
932	+/**
933	+ * Whether an attempt has a well-formed shape for the ruin's kind, which the clue already tells: a sequence of the
934	+ * right length of distinct known symbols, or one to `size²` compass moves. The check never looks at the answer.
935	+ */
936	+function attemptShapeOk(state: RuinsState, ruin: Ruin, attempt: unknown): attempt is RuinAttempt {
937	+  if (typeof attempt !== "object" || attempt === null) return false;
938	+  const candidate = attempt as Record<string, unknown>;
939	+  if (candidate.kind !== ruin.puzzle.kind) return false;
940	+  if (ruin.puzzle.kind === "sequence") {
941	+    const symbols = candidate.symbols;
942	+    if (!Array.isArray(symbols) || symbols.length !== ruin.puzzle.answer.length) return false;
943	+    const known: readonly string[] = state.rules.symbols;
944	+    return symbols.every((symbol) => typeof symbol === "string" && known.includes(symbol)) && new Set(symbols as RuinSymbol[]).size === symbols.length;
945	+  }
946	+  const moves = candidate.moves;
947	+  const longest = ruin.puzzle.size * ruin.puzzle.size;
948	+  const compass: readonly string[] = RUIN_MOVES;
949	+  return Array.isArray(moves) && moves.length > 0 && moves.length <= longest && moves.every((move) => typeof move === "string" && compass.includes(move));
950	+}
951	+
952	+/**
953	+ * Checks a player's attempt at the ruin they have open. A right answer solves the ruin for that player: the first
954	+ * solve unlocks the island's sources for everyone, and every player's first solve pays the completion gold. A wrong
955	+ * answer locks that player out of that ruin for `lockoutTicks`.
956	+ */
957	+export function answerRuin(state: RuinsState, request: AnswerRuinRequest): RuinStep<AnswerResult> {
958	+  const { playerId, island, tick, attempt } = request;
959	+  const ruin = isIsland(island) ? findRuin(state, island) : undefined;
960	+  const reject = (rejection: RuinRejection): RuinStep<AnswerResult> => ({
961	+    state,
962	+    result: { ok: false, rejection, outcome: null, lockedUntil: ruin && isPlayerId(playerId) ? lockedUntil(ruin, playerId) : 0, events: [] },
963	+  });
964	+  const bad = tickRejection(state, tick);
965	+  if (bad) return reject(bad);
966	+  if (!isPlayerId(playerId) || !isIsland(island)) return reject("invalid-request");
967	+  if (!ruin) return reject("unknown-ruin");
968	+  const presence = presenceOf(state, playerId);
969	+  if (presence.inDuel) return reject("in-duel");
970	+  if (presence.island !== island) return reject("not-at-ruin");
971	+  if (!sessionOf(ruin, playerId)) return reject("no-session");
972	+  if (hasSolved(ruin, playerId)) return reject("already-solved");
973	+  if (tick < lockedUntil(ruin, playerId)) return reject("locked-out");
974	+  if (!attemptShapeOk(state, ruin, attempt)) return reject("invalid-request");
975	+
976	+  if (!attemptSolves(ruin.puzzle, attempt)) {
977	+    const until = tick + state.rules.lockoutTicks;
978	+    const locked: Ruin = { ...ruin, lockouts: upsert(ruin.lockouts, playerId, { playerId, until }) };

