1587	+  if (index < last) hints.push(hint("right-before", answer[index + 1]!), hint("right-before", answer[index + 1]!));
1588	+  answer.forEach((other, position) => {
1589	+    if (position < index) hints.push(hint("after", other));
1590	+    if (position > index) hints.push(hint("before", other));
1591	+  });
1592	+  return hints;
1593	+}
1594	+
1595	+/** Draws of the six hints before falling back to the plainest unique set. */
1596	+const SEQUENCE_HINT_TRIES = 200;
1597	+
1598	+/**
1599	+ * Deals a sequence: the answer is uniform over every ordered choice of distinct symbols, then each tablet draws a true
1600	+ * hint until the hints together admit only the answer. The tablets stay in the rules' symbol order, so their layout
1601	+ * says nothing about the answer.
1602	+ */
1603	+export function generateSequence(rules: RuinRules, source: Draw): SequencePuzzle {
1604	+  const pool = [...rules.symbols];
