1618	+  const tablets = rules.symbols.map((symbol) => {
1619	+    const index = answer.indexOf(symbol);
1620	+    return { symbol, hint: index < 0 ? hint("absent") : hint("at", null, index) };
1621	+  });
1622	+  return { kind: "sequence", answer, tablets };
1623	+}
1624	+
1625	+// ---------------------------------------------------------------------------------------------------------------
1626	+// Navigation puzzles
1627	+
1628	+const STEPS: Readonly<Record<RuinMove, Cell>> = { N: { x: 0, y: -1 }, E: { x: 1, y: 0 }, S: { x: 0, y: 1 }, W: { x: -1, y: 0 } };
1629	+
1630	+function cellIndex(size: number, cell: Cell): number {
1631	+  return cell.y * size + cell.x;
1632	+}
1633	+
1634	+function cellAt(size: number, index: number): Cell {
1635	+  return { x: index % size, y: Math.floor(index / size) };
1636	+}
1637	+
1638	+/** Moves from start to goal over open cells, by breadth-first search; -1 when the goal cannot be reached. */
1639	+export function shortestPathMoves(size: number, start: Cell, goal: Cell, blocked: readonly Cell[]): number {
1640	+  const closed = new Set(blocked.map((cell) => cellIndex(size, cell)));
1641	+  if (closed.has(cellIndex(size, start)) || closed.has(cellIndex(size, goal))) return -1;
1642	+  const distance = new Map([[cellIndex(size, start), 0]]);
1643	+  const queue = [start];
1644	+  for (let head = 0; head < queue.length; head++) {
1645	+    const cell = queue[head]!;
1646	+    const moves = distance.get(cellIndex(size, cell))!;
1647	+    if (cell.x === goal.x && cell.y === goal.y) return moves;
1648	+    for (const move of RUIN_MOVES) {
1649	+      const next = { x: cell.x + STEPS[move].x, y: cell.y + STEPS[move].y };
1650	+      if (next.x < 0 || next.y < 0 || next.x >= size || next.y >= size) continue;
1651	+      const index = cellIndex(size, next);
1652	+      if (closed.has(index) || distance.has(index)) continue;
1653	+      distance.set(index, moves + 1);
1654	+      queue.push(next);
1655	+    }
1656	+  }
1657	+  return -1;
1658	+}
1659	+
1660	+/** Whether the moves walk from start to goal in exactly `minMoves` steps without leaving the grid or entering a block. */
1661	+export function walksToGoal(puzzle: NavigationPuzzle, moves: readonly RuinMove[]): boolean {
1662	+  if (moves.length !== puzzle.minMoves) return false;
1663	+  const closed = new Set(puzzle.blocked.map((cell) => cellIndex(puzzle.size, cell)));
1664	+  let cell = puzzle.start;
1665	+  for (const move of moves) {
1666	+    cell = { x: cell.x + STEPS[move].x, y: cell.y + STEPS[move].y };
1667	+    if (cell.x < 0 || cell.y < 0 || cell.x >= puzzle.size || cell.y >= puzzle.size) return false;
1668	+    if (closed.has(cellIndex(puzzle.size, cell))) return false;
1669	+  }
1670	+  return cell.x === puzzle.goal.x && cell.y === puzzle.goal.y;
1671	+}
1672	+
1673	+/** Layouts drawn before giving up; a draw outside the path bounds is simply drawn again. */
1674	+const NAVIGATION_TRIES = 10_000;
1675	+
1676	+/**
1677	+ * Deals a navigation grid: a start, a different goal and a number of blocked cells within the rules' bounds, drawn
1678	+ * again until the shortest path is within the rules' move bounds.
1679	+ */
1680	+export function generateNavigation(rules: RuinRules, source: Draw): NavigationPuzzle {
1681	+  const size = rules.gridSize;
1682	+  const cells = size * size;
1683	+  for (let attempt = 0; attempt < NAVIGATION_TRIES; attempt++) {
1684	+    const open = Array.from({ length: cells }, (_, index) => index);
1685	+    const take = () => open.splice(drawInt(source, open.length), 1)[0]!;
1686	+    const start = cellAt(size, take());
1687	+    const goal = cellAt(size, take());
1688	+    const count = rules.minBlockedCells + drawInt(source, rules.maxBlockedCells - rules.minBlockedCells + 1);
1689	+    const blocked = Array.from({ length: count }, take)
1690	+      .sort((a, b) => a - b)
1691	+      .map((index) => cellAt(size, index));
1692	+    const minMoves = shortestPathMoves(size, start, goal, blocked);
1693	+    if (minMoves >= rules.minPathMoves && minMoves <= rules.maxPathMoves) {
1694	+      return { kind: "navigation", size, start, goal, blocked, minMoves };
1695	+    }
1696	+  }
1697	+  throw new Error(`no ${size} × ${size} grid with a shortest path of ${rules.minPathMoves}–${rules.maxPathMoves} moves in ${NAVIGATION_TRIES} draws`);
1698	+}
1699	+
1700	+// ---------------------------------------------------------------------------------------------------------------
1701	+// Clues and answers
1702	+
1703	+/** The clue a player at the ruin reads. It is built field by field, so no secret can ride along. */
1704	+export function puzzleClue(puzzle: RuinPuzzle): RuinClue {
1705	+  if (puzzle.kind === "sequence") {
1706	+    return {
1707	+      kind: "sequence",
1708	+      length: puzzle.answer.length,
1709	+      tablets: puzzle.tablets.map((tablet) => ({ symbol: tablet.symbol, hint: { ...tablet.hint } })),
1710	+    };
1711	+  }
1712	+  return {
1713	+    kind: "navigation",
1714	+    size: puzzle.size,
1715	+    start: { ...puzzle.start },
1716	+    goal: { ...puzzle.goal },
1717	+    blocked: puzzle.blocked.map((cell) => ({ ...cell })),
1718	+  };
1719	+}
1720	+
1721	+/** Whether an attempt (already checked for shape) solves the puzzle. */
1722	+export function attemptSolves(puzzle: RuinPuzzle, attempt: RuinAttempt): boolean {
1723	+  if (puzzle.kind === "sequence") {
1724	+    return attempt.kind === "sequence" && attempt.symbols.length === puzzle.answer.length && attempt.symbols.every((symbol, index) => symbol === puzzle.answer[index]);
1725	+  }
1726	+  return attempt.kind === "navigation" && walksToGoal(puzzle, attempt.moves);
1727	+}
1728	+
1729	+const NAMES: Readonly<Record<RuinSymbol, string>> = { sun: "Sun", moon: "Moon", tide: "Tide", storm: "Storm", anchor: "Anchor", skull: "Skull" };
1730	+
1731	+function placeName(position: number, length: number): string {
1732	+  if (position === 0) return "first";
1733	+  if (position === length - 1) return "last";
