1	import { readdirSync, readFileSync } from "node:fs";
2	import { dirname, join, relative } from "node:path";
3	import { fileURLToPath } from "node:url";
4	import { describe, expect, it } from "vitest";
5	
6	/**
7	 * The authoritative packages stay pure (CLAUDE.md, §17): no Phaser, Colyseus, DOM, timers, wall-clock time or
8	 * Math.random, so the same match can be simulated headlessly and identically on client and server. Nor do they call
9	 * floating-point transcendental functions, whose results may differ between JavaScript engines (skeleton decision:
10	 * integer maths only, so `hashState` is engine-independent).
11	 */
12	const root = join(dirname(fileURLToPath(import.meta.url)), "../..");
13	const PURE_PACKAGES = ["packages/simulation", "packages/protocol", "packages/content"];
14	
15	const FORBIDDEN_MODULES: readonly RegExp[] = [
16	  /^phaser(\/|$)/,
17	  /^colyseus(\/|$)/,
18	  /^@colyseus\//,
19	  /^(node:)?timers(\/|$)/,
20	  /^(node:)?perf_hooks$/,
21	  /^(node:)?worker_threads$/,
22	  /^(node:)?(fs|net|http|https|dgram|child_process|os|process|crypto)(\/|$)/,
23	];
24	
25	const FORBIDDEN_CALLS: readonly [RegExp, string][] = [
26	  [/\bMath\.random\b/, "Math.random"],
27	  [/\bDate\.now\b/, "Date.now"],
28	  [/\bnew Date\b/, "new Date"],
29	  [/\bperformance\.now\b/, "performance.now"],
30	  [/\bprocess\.hrtime\b/, "process.hrtime"],
31	  [/\b(setTimeout|setInterval|setImmediate|queueMicrotask|requestAnimationFrame)\s*\(/, "timers"],
32	  [/\b(window|document|navigator|localStorage|sessionStorage)\s*[.[]/, "DOM globals"],
33	  [/\bcrypto\.(getRandomValues|randomUUID)\b/, "crypto randomness"],
34	  [
35	    /\bMath\.(sqrt|cbrt|hypot|pow|exp|expm1|log\w*|sin|cos|tan|asin|acos|atan|atan2|sinh|cosh|tanh|asinh|acosh|atanh)\b/,
36	    "floating-point transcendental Math functions",
37	  ],
38	];
39	
40	function sourceFiles(directory: string): string[] {
41	  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
42	    const path = join(directory, entry.name);
43	    if (entry.isDirectory()) return sourceFiles(path);
44	    return /\.(ts|tsx|js|mjs|cjs)$/.test(entry.name) ? [path] : [];
45	  });
46	}
47	
48	/** Source without comments or string contents, so that prose mentioning a forbidden call is not a violation. */
49	function code(source: string): string {
50	  return source
51	    .replace(/\/\*[\s\S]*?\*\//g, "")
52	    .replace(/(^|[^:])\/\/.*$/gm, "$1")
53	    .replace(/(["'`])(?:\\.|(?!\1)[^\\\n])*\1/g, '""');
54	}
55	
56	function importedModules(source: string): string[] {
57	  const specifiers: string[] = [];
58	  const patterns = [
59	    /\bimport\s+(?:type\s+)?(?:[\w*{}\s,$]+\s+from\s+)?["']([^"']+)["']/g,
60	    /\bexport\s+(?:type\s+)?[\w*{}\s,$]+\s+from\s+["']([^"']+)["']/g,
61	    /\bimport\s*\(\s*["']([^"']+)["']\s*\)/g,
62	    /\brequire\s*\(\s*["']([^"']+)["']\s*\)/g,
63	  ];
64	  for (const pattern of patterns) for (const match of source.matchAll(pattern)) specifiers.push(match[1]!);
65	  return specifiers;
66	}
67	
68	function violations(source: string): string[] {
69	  const found = importedModules(source)
70	    .filter((specifier) => FORBIDDEN_MODULES.some((pattern) => pattern.test(specifier)))
71	    .map((specifier) => `imports ${specifier}`);
72	  const stripped = code(source);
73	  for (const [pattern, label] of FORBIDDEN_CALLS) if (pattern.test(stripped)) found.push(`uses ${label}`);
74	  return found;
75	}
76	
77	describe("purity rule", () => {
78	  it("catches each forbidden dependency in a sample", () => {
79	    expect(violations('import Phaser from "phaser";')).toEqual(["imports phaser"]);
80	    expect(violations('import { Room } from "colyseus";')).toEqual(["imports colyseus"]);
81	    expect(violations('import type { Client } from "@colyseus/sdk";')).toEqual(["imports @colyseus/sdk"]);
82	    expect(violations('import { setTimeout } from "node:timers/promises";')).toEqual(["imports node:timers/promises"]);
83	    expect(violations('export { x } from "phaser/src/x";')).toEqual(["imports phaser/src/x"]);
84	    expect(violations('const m = await import("colyseus");')).toEqual(["imports colyseus"]);
85	    expect(violations("const r = Math.random();")).toEqual(["uses Math.random"]);
86	    expect(violations("const t = Date.now();")).toEqual(["uses Date.now"]);
87	    expect(violations("setInterval(tick, 16);")).toEqual(["uses timers"]);
88	    expect(violations("document.body.append(x);")).toEqual(["uses DOM globals"]);
89	    const transcendental = ["uses floating-point transcendental Math functions"];
90	    expect(violations("const d = Math.sqrt(x * x + y * y);")).toEqual(transcendental);
91	    for (const call of ["Math.cbrt(v)", "Math.hypot(x, y)", "Math.pow(2, n)", "Math.exp(t)", "Math.log2(n)", "Math.atan2(y, x)", "Math.sin(a)"]) {
92	      expect(violations(`const r = ${call};`)).toEqual(transcendental);
93	    }
94	    expect(violations("const r = Math.floor(Math.sign(x) * Math.imul(a, b));")).toEqual([]);
95	    expect(violations('// Math.random is banned\nconst s = "Date.now";')).toEqual([]);
96	  });
97	
98	  for (const pkg of PURE_PACKAGES) {
99	    describe(pkg, () => {
100	      it("imports and calls nothing impure", () => {
101	        const files = sourceFiles(join(root, pkg, "src"));
102	        expect(files.length).toBeGreaterThan(0);
103	        const report = files.flatMap((file) =>
104	          violations(readFileSync(file, "utf8")).map((violation) => `${relative(root, file)} ${violation}`),
105	        );
106	        expect(report).toEqual([]);
107	      });
108	
109	      it("depends on no impure package", () => {
110	        const manifest = JSON.parse(readFileSync(join(root, pkg, "package.json"), "utf8")) as Record<string, unknown>;
111	        const names = ["dependencies", "peerDependencies", "optionalDependencies"].flatMap((field) =>
112	          Object.keys((manifest[field] as Record<string, string> | undefined) ?? {}),
113	        );
114	        expect(names.filter((name) => FORBIDDEN_MODULES.some((pattern) => pattern.test(name)))).toEqual([]);
115	      });
116	
117	      it("leaves the DOM library out of its tsconfig", () => {
118	        const tsconfig = JSON.parse(readFileSync(join(root, pkg, "tsconfig.json"), "utf8")) as {
119	          compilerOptions: { lib?: string[]; types?: string[] };
120	        };
121	        const lib = tsconfig.compilerOptions.lib;
122	        expect(lib).toBeDefined();
123	        expect(lib!.map((entry) => entry.toLowerCase()).filter((entry) => entry.startsWith("dom"))).toEqual([]);
124	        expect(tsconfig.compilerOptions.types).toEqual([]);
125	      });
126	    });
127	  }
128	});
